"""Build actual discovery for the implemented read-only content services."""
import pathlib,json,hashlib,shutil,re,html
BASE='https://vpspricewatch.com'
def generate(out):
 from agent_readiness import Markdown
 out=pathlib.Path(out);root=pathlib.Path(__file__).parent
 def write(n,t):p=out/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(t,encoding='utf-8')
 def doc(n,data):write(n,json.dumps(data,ensure_ascii=False,indent=2))
 public=json.loads((root/'agent-public-jwk.json').read_text(encoding='utf-8'))
 items=[]
 for p in sorted(out.rglob('*.html')):
  if p.name=='404.html' or p.relative_to(out).parts[0]=='ai':continue
  rel=p.relative_to(out).as_posix();url='/' if rel=='index.html' else '/'+(rel[:-10] if rel.endswith('/index.html') else rel[:-5])
  raw=p.read_text(encoding='utf-8');m=Markdown();m.feed(raw);text=m.text();h=re.search(r'<h1[^>]*>(.*?)</h1>',raw,re.S)
  if text.strip():items.append({'url':BASE+url,'title':html.unescape(re.sub('<[^>]+>','',h.group(1))) if h else url,'text':text})
 doc('ai/content.json',items)
 doc('.well-known/jwks.json',{'keys':[public]})
 api=BASE+'/api/content'
 catalog={'linkset':[{'anchor':api,'service-desc':[{'href':BASE+'/ai/openapi.json','type':'application/vnd.oai.openapi+json'}],'service-doc':[{'href':BASE+'/ai/','type':'text/html'}],'status':[{'href':BASE+'/api/health','type':'application/json'}]}]}
 doc('.well-known/api-catalog',catalog)
 schema={'type':'object','properties':{'items':{'type':'array','items':{'type':'object','properties':{'url':{'type':'string','format':'uri'},'title':{'type':'string'},'excerpt':{'type':'string'}}}}}}
 doc('ai/openapi.json',{'openapi':'3.1.0','info':{'title':'VPS Price Watch read-only content','version':'1.0.0'},'servers':[{'url':BASE}],'paths':{'/api/content':{'get':{'operationId':'searchPublishedContent','summary':'Search published content snapshots','parameters':[{'name':'q','in':'query','schema':{'type':'string','maxLength':200}}],'responses':{'200':{'description':'Published page matches, not checkout verification','content':{'application/json':{'schema':schema}}}}}},'/api/agent/content':{'get':{'operationId':'readWithAgentCredential','security':[{'agentOAuth':['content:read']}],'parameters':[{'name':'q','in':'query','schema':{'type':'string','maxLength':200}}],'responses':{'200':{'description':'Read-only published page matches'},'401':{'description':'Missing or invalid bearer token'}}}},'/api/health':{'get':{'operationId':'health','responses':{'200':{'description':'Operational read-only service'}}}}},'components':{'securitySchemes':{'agentOAuth':{'type':'oauth2','flows':{'clientCredentials':{'tokenUrl':BASE+'/oauth/token','scopes':{'content:read':'Read public published content only'}}}}}}})
 auth={'issuer':BASE,'token_endpoint':BASE+'/oauth/token','registration_endpoint':BASE+'/oauth/register','jwks_uri':BASE+'/.well-known/jwks.json','grant_types_supported':['client_credentials'],'response_types_supported':[],'token_endpoint_auth_methods_supported':['client_secret_post'],'scopes_supported':['content:read'],'service_documentation':BASE+'/auth.md','agent_auth':{'skill':BASE+'/auth.md','register_uri':BASE+'/oauth/register','identity_types_supported':['anonymous'],'anonymous':{'credential_types_supported':['oauth2_client_credentials'],'claim_uri':BASE+'/oauth/register'}}}
 doc('.well-known/oauth-authorization-server',auth)
 doc('.well-known/oauth-protected-resource',{'resource':BASE,'authorization_servers':[BASE],'scopes_supported':['content:read'],'bearer_methods_supported':['header'],'resource_documentation':BASE+'/auth.md'})
 write('auth.md','# VPS Price Watch auth.md\n\n## Agent audience and scope\nThis service offers anonymous machine registration for read-only access to already-public content. It does not authenticate a human, expose private account data, accept orders or grant write permissions.\n\n## Agent registration metadata\nagent_auth: anonymous\nregister_uri: https://vpspricewatch.com/oauth/register\nidentity_types_supported: anonymous\ncredential_types_supported: oauth2_client_credentials\nclaim_uri: https://vpspricewatch.com/oauth/register\n\n## Registration\nPOST /oauth/register with Content-Type: application/json and {"grant_types":["client_credentials"],"scope":"content:read","token_endpoint_auth_method":"client_secret_post"}. The response returns client_id and client_secret. Keep the secret private. It expires after 24 hours; register again after expiry. No email or payment is required.\n\n## Credential use\nPOST /oauth/token with application/x-www-form-urlencoded fields grant_type=client_credentials, client_id, client_secret and scope=content:read. Send the returned access_token only in Authorization: Bearer on GET /api/agent/content?q=namesilo. Access tokens expire after 600 seconds and use RS256 signatures. Public verification keys are at /.well-known/jwks.json. No refresh token, user authorization grant or early credential revocation endpoint is offered. Rotating the signing key invalidates existing credentials.\n\n## Public alternative\nGET /api/content?q=namesilo needs no credential. Both routes search published snapshots and preserve source page links. They do not verify current checkout availability.\n')
 mcp={'serverInfo':{'name':'vps-price-watch-read-only','version':'1.0.0'},'description':'Read-only search of public published content; no checkout or external fetching.','transport':{'type':'streamable-http','endpoint':BASE+'/mcp'},'endpoint':BASE+'/mcp','capabilities':{'tools':{}},'authentication':{'required':False},'documentationUrl':BASE+'/ai/'}
 doc('.well-known/mcp/server-card.json',mcp)
 card={'protocolVersion':'0.3.0','name':'VPS Price Watch content finder','version':'1.0.0','description':'Deterministic search of this site’s published public page snapshots. Not a generative adviser or purchase agent.','url':BASE+'/a2a','preferredTransport':'JSONRPC','supportedInterfaces':[{'url':BASE+'/a2a','transport':'JSONRPC'}],'capabilities':{'streaming':False,'pushNotifications':False},'defaultInputModes':['text/plain'],'defaultOutputModes':['text/plain'],'skills':[{'id':'find-published-content','name':'Find published content','description':'Return up to ten relevant page links and excerpts for a text query.','tags':['read-only','hosting','domains'],'examples':['namesilo','vultr']} ]}
 doc('.well-known/agent-card.json',card)
 index='::ILANG\n[TYPE:index][SITE:vpspricewatch.com][MODE:read-only]\n::RESOURCE{directory|url:https://vpspricewatch.com/ai/}\n::RESOURCE{content_api|url:https://vpspricewatch.com/api/content}\n::RESOURCE{api_spec|url:https://vpspricewatch.com/ai/openapi.json}\n::RESOURCE{api_catalog|url:https://vpspricewatch.com/.well-known/api-catalog}\n::RESOURCE{mcp|url:https://vpspricewatch.com/mcp}\n::RESOURCE{agent_card|url:https://vpspricewatch.com/.well-known/agent-card.json}\n::RESOURCE{skills|url:https://vpspricewatch.com/.well-known/agent-skills/index.json}\n::RESOURCE{auth|url:https://vpspricewatch.com/auth.md}\n::BOUNDARY{never:checkout or private data access}\n'
 write('ai/index.ilang',index)
 links=[('/api/content?q=namesilo','Search published NameSilo content'),('/ai/content.json','Published content snapshots'),('/ai/openapi.json','OpenAPI description'),('/.well-known/api-catalog','API catalog'),('/ai/index.ilang','I-Lang directory'),('/.well-known/mcp/server-card.json','MCP service card'),('/.well-known/agent-card.json','A2A content finder card'),('/auth.md','Agent credential instructions'),('/.well-known/agent-skills/index.json','Reading skill index')]
 write('ai/index.html','<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Public content access | VPS Price Watch</title><link rel="canonical" href="'+BASE+'/ai/"><style>body{max-width:760px;margin:40px auto;padding:0 20px;font:18px/1.6 system-ui}a{overflow-wrap:anywhere}</style></head><body><main><h1>Read published hosting and domain information</h1><p>Use these working read-only access routes to find published pages and their recorded evidence. No purchase, account changes or private provider data are available. Offer details remain snapshots; confirm the official source before paying.</p><ul>'+''.join('<li><a href="'+u+'">'+t+'</a></li>' for u,t in links)+'</ul><p>The content finder returns matching published links, not generated purchase advice. Browser tools are available where the browser implements WebMCP.</p><p><a href="/">Return to VPS Price Watch</a></p></main></body></html>')
 webmcp="""(()=>{const ctx=document.modelContext||navigator.modelContext;if(!ctx?.registerTool)return;ctx.registerTool({name:'search_published_offers',description:'Read-only search of published hosting and domain offer pages; no checkout.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async({query})=>{const u=new URL('/api/content',location.origin);u.searchParams.set('q',query);const r=await fetch(u);if(!r.ok)throw Error('Content lookup failed');return {content:[{type:'text',text:JSON.stringify(await r.json())}]};}});})();"""
 write('ai/browser-tools.js',webmcp)
 shutil.copy2(root/'agent_services.js',out/'agent_services.js')
 worker=(out/'_worker.js').read_text(encoding='utf-8')
 worker="import {service} from './agent_services.js';\nconst PUBLIC_JWK="+json.dumps(public)+";\n"+worker
 worker=worker.replace("const url = new URL(request.url);","env={...env,PUBLIC_JWK};\n const action=await service(request,env);if(action)return action;\n const url = new URL(request.url);")
 worker=worker.replace("const original=await env.ASSETS.fetch(request);","let original=await env.ASSETS.fetch(request);\n if(original.ok&&(original.headers.get('Content-Type')||'').includes('text/html')&&request.method==='GET'){\n  const text=await original.text(); const injected=text.replace('</head>','<script src=\"/ai/browser-tools.js\" defer></script></head>');\n  original=new Response(injected,original);original.headers.delete('Content-Length');original.headers.delete('ETag');\n }\n if(path==='/.well-known/api-catalog'){original=new Response(original.body,original);original.headers.set('Content-Type','application/linkset+json');}\n if(path.startsWith('/.well-known/oauth-')){original=new Response(original.body,original);original.headers.set('Content-Type','application/json');}\n if(path==='/ai/index.ilang'){original=new Response(original.body,original);original.headers.set('Content-Type','text/plain; charset=utf-8');}")
 worker=worker.replace("const links = '","const links = '</.well-known/api-catalog>; rel=\"api-catalog\", ")
 write('_worker.js',worker)
 # Replace the previous accurate-at-the-time absence statements with the implemented scope.
 llms=(out/'llms.txt').read_text(encoding='utf-8').replace('We do not operate checkout, agent registration, an MCP server or an A2A service.','Public read-only content services and agent credentials are documented at /ai/ and /auth.md. No checkout is provided.')
 write('llms.txt',llms)
 skillpath='.well-known/agent-skills/read-official-offers/SKILL.md';skill=(out/skillpath).read_text(encoding='utf-8').replace('No registration, payment, OAuth credentials, MCP endpoint or A2A endpoint is provided.','No registration is required for these public GET requests. Optional read-only content credentials and protocol endpoints are documented at /ai/ and /auth.md. No payments are accepted.')
 write(skillpath,skill);skills=json.loads((out/'.well-known/agent-skills/index.json').read_text(encoding='utf-8'));skills['skills'][0]['digest']='sha256:'+hashlib.sha256(skill.encode()).hexdigest();doc('.well-known/agent-skills/index.json',skills)
